        "Ima tudi pomen zgodovina: Geschichte lernen (učiti se zgodovino), die Geschichte Europas. Pomen določi sobesedilo.",
        "Pogoste zveze: eine Geschichte erzählen (pripovedovati zgodbo), eine Geschichte lesen."
