        "Am Morgen (am = an dem) pomeni »zjutraj«. Za ponavljanje se uporablja morgens (vsako jutro / zjutraj, prislov): Ich stehe morgens um sechs auf.",
        "Razlika od morgen: morgen (z malo začetnico) je »jutri«, der Morgen — »jutro«."
